 import React, { useState, useEffect, useRef } from 'react'
import { supabase } from '../lib/supabase'
import { useAuth } from '../contexts/AuthContext'
import { useToast } from '../contexts/ToastContext'
import { Link } from 'react-router-dom'
import PostCard from '../components/PostCard'
import PredictionCard from '../components/PredictionCard'
import FollowButton from '../components/follow/FollowButton'
import { SkeletonFeed } from '../components/Skeleton'

export default function Feed() {
    const { user, profile } = useAuth()
    const { showToast } = useToast()
    const [feedItems, setFeedItems] = useState([])
    const [loading, setLoading] = useState(true)
    const [newPost, setNewPost] = useState('')
    const [posting, setPosting] = useState(false)
    const [selectedImage, setSelectedImage] = useState(null)
    const [imagePreview, setImagePreview] = useState(null)
    const [filter, setFilter] = useState('all')
    const fileInputRef = useRef(null)

    useEffect(() => {
        loadFeed()
    }, [filter])

    const loadFeed = async () => {
        setLoading(true)
        try {
            // 1. Fetch social posts WITH is_verified
            let postsQuery = supabase
                .from('posts')
                .select(`
                    *,
                    profiles:user_id (id, username, full_name, avatar_url, is_verified),
                    comments:post_comments (
                        *,
                        profiles:user_id (id, username, full_name, avatar_url, is_verified),
                        replies:comment_replies (
                            *,
                            profiles:user_id (id, username, full_name, avatar_url, is_verified)
                        )
                    ),
                    reactions:post_reactions (type, user_id)
                `)
                .order('created_at', { ascending: false })
                .limit(50)

            // 2. Fetch public predictions WITH is_verified
            let predictionsQuery = supabase
                .from('public_predictions')
                .select(`
                    *,
                    profiles:user_id (id, username, full_name, avatar_url, is_verified)
                `)
                .order('created_at', { ascending: false })
                .limit(50)

            // Apply following filter
            if (filter === 'following' && user) {
                const { data: following } = await supabase
                    .from('followers')
                    .select('following_id')
                    .eq('follower_id', user.id)

                const followingIds = following?.map(f => f.following_id) || []
                if (followingIds.length > 0) {
                    postsQuery = postsQuery.in('user_id', followingIds)
                    predictionsQuery = predictionsQuery.in('user_id', followingIds)
                } else {
                    setFeedItems([])
                    setLoading(false)
                    return
                }
            }

            const [postsResult, predictionsResult] = await Promise.all([
                postsQuery,
                predictionsQuery
            ])

            const posts = postsResult.data || []
            const predictions = predictionsResult.data || []

            // 3. Combine and sort by created_at
            const combined = [
                ...posts.map(item => ({ ...item, type: 'post' })),
                ...predictions.map(item => ({ ...item, type: 'prediction' }))
            ]

            combined.sort((a, b) => new Date(b.created_at) - new Date(a.created_at))

            setFeedItems(combined)
        } catch (error) {
            console.error('Error loading feed:', error)
            showToast('Failed to load feed', 'error')
        } finally {
            setLoading(false)
        }
    }

    const handleImageUpload = (e) => {
        const file = e.target.files[0]
        if (file) {
            if (file.size > 5 * 1024 * 1024) {
                showToast('Image too large. Max 5MB.', 'error')
                return
            }
            setSelectedImage(file)
            const reader = new FileReader()
            reader.onload = () => {
                setImagePreview(reader.result)
            }
            reader.readAsDataURL(file)
        }
    }

    const removeImage = () => {
        setSelectedImage(null)
        setImagePreview(null)
        if (fileInputRef.current) {
            fileInputRef.current.value = ''
        }
    }

    const handleCreatePost = async (e) => {
        e.preventDefault()
        if (!newPost.trim() && !selectedImage) {
            showToast('Please write something or add an image', 'warning')
            return
        }

        setPosting(true)
        try {
            let imageUrl = null
            if (selectedImage) {
                const reader = new FileReader()
                const imageData = await new Promise((resolve) => {
                    reader.onload = () => resolve(reader.result)
                    reader.readAsDataURL(selectedImage)
                })
                imageUrl = imageData
            }

            const { data, error } = await supabase
                .from('posts')
                .insert({
                    user_id: user.id,
                    text: newPost.trim(),
                    image: imageUrl,
                    likes_count: 0,
                    comments_count: 0
                })
                .select()
                .single()

            if (error) throw error

            showToast('Post shared successfully! 🎉', 'success')
            setNewPost('')
            removeImage()
            await loadFeed()
        } catch (error) {
            console.error('Error creating post:', error)
            showToast('Failed to create post', 'error')
        } finally {
            setPosting(false)
        }
    }

    const renderFeedItem = (item) => {
        if (item.type === 'post') {
            return (
                <PostCard
                    key={item.id}
                    post={item}
                    onRefresh={loadFeed}
                    currentUser={user}
                />
            )
        } else {
            return (
                <PredictionCard
                    key={item.id}
                    prediction={item}
                    onRefresh={loadFeed}
                    currentUser={user}
                />
            )
        }
    }

    return (
        <div className="max-w-3xl mx-auto">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h1 className="text-2xl font-bold text-gray-800">📰 Feed</h1>
                    <p className="text-gray-500">Social posts and public predictions from the community</p>
                </div>
                <div className="flex gap-2">
                    <button
                        onClick={() => setFilter('all')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'all'
                                ? 'bg-green-600 text-white'
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        All
                    </button>
                    <button
                        onClick={() => setFilter('following')}
                        className={`px-4 py-2 rounded-lg text-sm font-medium transition ${
                            filter === 'following'
                                ? 'bg-green-600 text-white'
                                : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                        }`}
                    >
                        Following
                    </button>
                </div>
            </div>

            {/* Create Post */}
            <div className="bg-white rounded-xl shadow-md p-4 mb-6">
                <div className="flex items-center gap-3 mb-3">
                    <div className="w-10 h-10 bg-green-500 rounded-full flex items-center justify-center text-white font-bold">
                        {profile?.username?.[0]?.toUpperCase() || 'U'}
                    </div>
                    <span className="font-semibold text-gray-800">
                        {profile?.full_name || profile?.username || 'User'}
                    </span>
                </div>

                <form onSubmit={handleCreatePost}>
                    <textarea
                        value={newPost}
                        onChange={(e) => setNewPost(e.target.value)}
                        placeholder="What's on your mind? Share a prediction, analysis, or football news..."
                        className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-green-500 resize-none"
                        rows="3"
                    />

                    {imagePreview && (
                        <div className="relative mt-3">
                            <img 
                                src={imagePreview} 
                                alt="Preview" 
                                className="max-h-64 rounded-lg object-contain bg-gray-100"
                            />
                            <button
                                type="button"
                                onClick={removeImage}
                                className="absolute top-2 right-2 bg-red-500 text-white rounded-full w-8 h-8 flex items-center justify-center hover:bg-red-600"
                            >
                                ×
                            </button>
                        </div>
                    )}

                    <div className="flex items-center justify-between mt-3">
                        <div className="flex gap-2">
                            <button
                                type="button"
                                onClick={() => fileInputRef.current?.click()}
                                className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition text-sm"
                            >
                                📷 Add Image
                            </button>
                            <input
                                ref={fileInputRef}
                                type="file"
                                accept="image/*"
                                onChange={handleImageUpload}
                                className="hidden"
                            />
                        </div>
                        <button
                            type="submit"
                            disabled={posting || (!newPost.trim() && !selectedImage)}
                            className="px-6 py-2 bg-green-600 text-white rounded-lg font-semibold hover:bg-green-700 transition disabled:opacity-50"
                        >
                            {posting ? 'Posting...' : 'Post'}
                        </button>
                    </div>
                </form>
            </div>

            {/* Feed Items */}
            {loading ? (
                <SkeletonFeed />
            ) : feedItems.length === 0 ? (
                <div className="text-center py-16 bg-white rounded-xl shadow-md">
                    <div className="text-6xl mb-4">📭</div>
                    <h3 className="text-xl font-bold text-gray-700 mb-2">Your feed is empty</h3>
                    <p className="text-gray-500 max-w-sm mx-auto">
                        Start by sharing a post or following other users to see their content here.
                    </p>
                    <div className="flex gap-4 justify-center mt-6 flex-wrap">
                        <Link 
                            to="/matches"
                            className="bg-green-600 text-white px-6 py-2 rounded-lg hover:bg-green-700 transition"
                        >
                            Make a Prediction
                        </Link>
                        <button
                            onClick={() => document.querySelector('textarea')?.focus()}
                            className="bg-gray-200 text-gray-700 px-6 py-2 rounded-lg hover:bg-gray-300 transition"
                        >
                            Create Post
                        </button>
                    </div>
                </div>
            ) : (
                <div className="space-y-6">
                    {feedItems.map(renderFeedItem)}
                </div>
            )}
        </div>
    )
}
